PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prevLevel : INT := 0;
    lowLimit : INT := 10;
    highLimit : INT := 90;
    pumpTimer : TON;
END_VAR

IF Level <= lowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
    pumpTimer(IN := TRUE, PT := T#1s);
ELSIF Level >= highLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
    pumpTimer(IN := FALSE);
END_IF;

IF pumpTimer.Q AND (Level >= highLimit OR Level <= lowLimit) THEN
    PumpIn := FALSE;
END_IF;

prevLevel := Level;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Safety check: PumpIn should never run when Level >= HighLimit
IF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF;

// Control logic for PumpIn and ValveOut
IF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Hysteresis control for PumpIn
IF NOT PumpTimer.Q AND (Level > LowLimit OR Level < HighLimit) THEN
    PumpTimer(IN := TRUE, PT := T#1s);
END_IF;

IF PumpTimer.Q THEN
    PumpIn := TRUE;
ELSE
    PumpIn := FALSE;
END_IF;

END_PROGRAM

