PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    SafetyTimer : TON;
END_VAR

// Set safety timer if level is above high limit
SafetyTimer(IN := Level >= HighLimit, PT := T#5s);

// Control logic for inlet pump and outlet valve
IF SafetyTimer.Q THEN
    PumpIn := FALSE;
ELSE
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
    ELSE
        PumpIn := FALSE;
    END_IF;

    IF Level >= HighLimit THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    prevLevel : INT := 0;
    levelHighLimit : INT := 90;
    levelLowLimit : INT := 10;
    PumpInTimer : TON;
END_VAR

// Check if the level has changed since last iteration
IF Level <> prevLevel THEN
    // Reset the timer on level change
    PumpInTimer(IN := FALSE);
END_IF;

// Determine the state of the inlet pump
IF Level <= levelLowLimit THEN
    PumpIn := TRUE;
    PumpInTimer(IN := TRUE, PT := T#1s); // Start timer for hysteresis
ELSIF Level >= levelHighLimit THEN
    PumpIn := FALSE;
ELSE
    PumpIn := PumpInTimer.Q; // Use timer output to maintain previous state
END_IF;

// Always open the outlet valve at or above the high limit
IF Level >= levelHighLimit THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

// Safety check: ensure pump does not run when level is at or above the high limit
IF PumpIn AND Level >= levelHighLimit THEN
    PumpIn := FALSE;
END_IF;

// Update the previous level
prevLevel := Level;
END_PROGRAM

