    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    ConveyorRunning : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault AND NOT ConveyorRunning, PT := T#0s);

IF StopPB OR NOT GuardClosed OR Fault THEN
    ConveyorRunning := FALSE;
END_IF;

IF StartTimer.Q AND NOT ConveyorRunning THEN
    ConveyorRunning := TRUE;
END_IF;

Conveyor := ConveyorRunning;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    ConveyorRunning : BOOL := FALSE;
    StartTimer : TON;
END_VAR

// Initialize timer with a preset time of 0 seconds
StartTimer(IN := StartPB AND GuardClosed AND NOT Fault, PT := T#0s);

// If Start button is pressed and safety conditions met, start the conveyor
IF StartTimer.Q THEN
    ConveyorRunning := TRUE;
END_IF;

// Check for stop conditions
IF StopPB OR NOT GuardClosed OR Fault THEN
    ConveyorRunning := FALSE;
END_IF;

// Assign output based on running state
Conveyor := ConveyorRunning;
END_PROGRAM

