PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R : BOOL;
    EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    NS_green : TON;
    NS_yellow : TON;
    NS_allred : TON;
    EW_green : TON;
    EW_yellow : TON;
    EW_allred : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

NS_green(IN := State = 0 OR State = 3, PT := PT_GREEN);
NS_yellow(IN := State = 1 OR State = 4, PT := PT_YELLOW);
NS_allred(IN := State = 2 OR State = 5, PT := PT_ALLRED);

EW_green(IN := State = 3 OR State = 0, PT := PT_GREEN);
EW_yellow(IN := State = 4 OR State = 1, PT := PT_YELLOW);
EW_allred(IN := State = 5 OR State = 2, PT := PT_ALLRED);

NS_G := NS_green.Q AND NOT (NS_yellow.Q OR NS_allred.Q);
NS_Y := NS_yellow.Q AND NOT (NS_green.Q OR NS_allred.Q);
NS_R := NS_allred.Q AND NOT (NS_green.Q OR NS_yellow.Q);

EW_G := EW_green.Q AND NOT (EW_yellow.Q OR EW_allred.Q);
EW_Y := EW_yellow.Q AND NOT (EW_green.Q OR EW_allred.Q);
EW_R := EW_allred.Q AND NOT (EW_green.Q OR EW_yellow.Q);

CASE State OF
    0: IF NS_green.Q THEN State := 1; END_IF;
    1: IF NS_yellow.Q THEN State := 2; END_IF;
    2: IF NS_allred.Q THEN State := 3; END_IF;
    3: IF EW_green.Q THEN State := 4; END_IF;
    4: IF EW_yellow.Q THEN State := 5; END_IF;
    5: IF EW_allred.Q THEN State := 0; END_IF;
END_CASE;

END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    NS_green, NS_yellow, NS_allred, EW_green, EW_yellow, EW_allred : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

NS_green(IN := State = 0 OR State = 3, PT := PT_GREEN);
NS_yellow(IN := State = 1 OR State = 4, PT := PT_YELLOW);
NS_allred(IN := State = 2 OR State = 5, PT := PT_ALLRED);

EW_green(IN := State = 3 OR State = 0, PT := PT_GREEN);
EW_yellow(IN := State = 4 OR State = 1, PT := PT_YELLOW);
EW_allred(IN := State = 5 OR State = 2, PT := PT_ALLRED);

NS_G := NS_green.Q AND NOT NS_yellow.Q AND NOT NS_allred.Q;
NS_Y := NS_yellow.Q AND NOT NS_green.Q AND NOT NS_allred.Q;
NS_R := NS_allred.Q AND NOT NS_green.Q AND NOT NS_yellow.Q;

EW_G := EW_green.Q AND NOT EW_yellow.Q AND NOT EW_allred.Q;
EW_Y := EW_yellow.Q AND NOT EW_green.Q AND NOT EW_allred.Q;
EW_R := EW_allred.Q AND NOT EW_green.Q AND NOT EW_yellow.Q;

CASE State OF
    0:
        IF NS_green.Q THEN
            State := 1;
        ELSIF NS_allred.Q THEN
            State := 2;
        END_IF;
    1:
        IF NS_yellow.Q THEN
            State := 0;
        ELSIF NS_allred.Q THEN
            State := 2;
        END_IF;
    2:
        IF NS_allred.Q THEN
            State := 0;
        END_IF;
    3:
        IF EW_green.Q THEN
            State := 4;
        ELSIF EW_allred.Q THEN
            State := 5;
        END_IF;
    4:
        IF EW_yellow.Q THEN
            State := 3;
        ELSIF EW_allred.Q THEN
            State := 5;
        END_IF;
