PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R : BOOL;
    EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    TNS_G, TEW_G, Tall_red : TON;
END_VAR

// Timers presets in ticks
CONST
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_CONST

TNS_G(IN := State = 0 OR State = 3, PT := PT_GREEN);
TEW_G(IN := State = 3 OR State = 0, PT := PT_GREEN);
Tall_red(IN := State = 2 OR State = 5, PT := PT_ALLRED);

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := TRUE;
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := TRUE;
    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
END_CASE

// Safety check to ensure no simultaneous movement aspects
IF (NS_G OR NS_Y) AND (EW_G OR EW_Y) THEN
    // Handle safety violation (e.g., stop execution or log error)
    NS_G := FALSE;
    NS_Y := FALSE;
    NS_R := TRUE;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := TRUE;
END_IF

State := State + 1;
IF State > 5 THEN
    State := 0;
END_IF
END_PROGRAM

PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    TON_NS_GREEN, TON_NS_YELLOW, TON_NS_ALLRED, TON_EW_GREEN, TON_EW_YELLOW, TON_EW_ALLRED : TON;
    PT_GREEN, PT_YELLOW, PT_ALLRED : TIME := T#1s; // Adjusted to match the requirement
END_VAR

// Initialize State
State := 0;

// Main loop
WHILE TRUE DO
    CASE State OF
        0:
            NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
            EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
            TON_NS_GREEN(IN := NS_G, PT := PT_GREEN);
            TON_EW_RED(IN := NOT NS_G AND NOT NS_Y, PT := PT_ALLRED);
            IF TON_NS_GREEN.Q THEN
                State := 1;
            ELSIF TON_EW_RED.Q THEN
                State := 2;
            END_IF;

        1:
            NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
