    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND NOT EStop THEN
    CASE State OF
        0:  // Idle
            IF Level >= LIQ_MIN THEN
                State := 1;
            END_IF;
        1:  // Fill
            IF Level >= LVL_HIGH THEN
                State := 2;
            ELSE
                FillValve := TRUE;
            END_IF;
        2:  // Heat
            IF Temp >= TEMP_SET THEN
                State := 3;
            ELSE
                Heater := TRUE;
                Agitator := TRUE;
            END_IF;
        3:  // React
            IF NOT FillTimer.Q AND Not DrainTimer.Q THEN
                State := 4;
            ELSE
                Heater := TRUE;
                Agitator := TRUE;
            END_IF;
        4:  // Drain
            IF Level <= LVL_LOW THEN
                State := 0;
            ELSE
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Safety checks
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

