    State := 1;
    Pump := TRUE;
    Valve := FALSE;
ELSIF State = 1 AND Level >= HIGH THEN
    State := 2;
    Pump := FALSE;
    Valve := TRUE;
ELSIF State = 2 AND Level <= LOW THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

