IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
ELSIF Level >= HIGH AND Pump THEN
    Pump := FALSE;
ELSIF Level <= LOW AND Valve THEN
    Valve := FALSE;
END_IF;
END_PROGRAM

