LeadChangeTimer(IN := NOT PrevDemand AND Demand, PT := T#1s);

IF EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF LeadChangeTimer.Q THEN
        Lead := 1 - Lead;
        LeadChangeTimer(IN := FALSE);
    END_IF;

    CASE Lead OF
        0 :
            Pump1 := Demand;
            Pump2 := FALSE;
        1 :
            Pump1 := FALSE;
            Pump2 := Demand;
