    Lead := 0;
    PrevDemand := FALSE;
ELSE
    DemandTimer(IN := Demand AND NOT PrevDemand, PT := T#0s);

    IF DemandTimer.Q THEN
        Pump1 := (Lead = 0) AND Demand;
        Pump2 := (Lead = 1) AND Demand;

