PROGRAM gate
VAR
    State : INT;
    MotorOpen : BOOL;
    MotorClose : BOOL;
    T_Open : TON;
    T_Close : TON;
END_VAR

// Initialize State
State := 0;

// Main logic
CASE State OF
    0: // Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
            T_Open(IN := TRUE, PT := T#0s);
        ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := 2;
            T_Close(IN := TRUE, PT := T#0s);
        END_IF;

    1: // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            MotorOpen := FALSE;
            T_Open(IN := FALSE);
            IF OpenLimit THEN
                State := 0;
            ELSE
                State := 3; // Obstructed while opening
            END_IF;
        END_IF;

    2: // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            MotorClose := FALSE;
            T_Close(IN := FALSE);
            IF CloseLimit THEN
                State := 0;
            ELSE
                State := 4; // Obstructed while closing
            END_IF;
        END_IF;

    3: // Obstructed while opening
        MotorOpen := FALSE;
        MotorClose := FALSE;
        T_Open(IN := FALSE);
        IF NOT Obstruction THEN
            State := 1;
            T_Open(IN := TRUE, PT := T#0s);
        END_IF;

    4: // Obstructed while closing
        MotorOpen := FALSE;
        MotorClose := FALSE;
        T_Close(IN := FALSE);
        IF NOT Obstruction AND NOT CloseCmd THEN
            State := 2;
            T_Close(IN := TRUE, PT := T#0s);
        END_IF;
END_CASE;

END_PROGRAM

