PROGRAM conveyor3
VAR
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
    State : INT;
    TON_C1 : TON;
    TON_C2 : TON;
END_VAR

State := 0;

IF EStop = FALSE THEN
    IF StopPB = FALSE THEN
        CASE State OF
            0:
                IF StartPB = TRUE THEN
                    State := 1;
                END_IF;
            1:
                IF TON_C2.Q = TRUE THEN
                    State := 2;
                END_IF;
            2:
                IF TON_C3.Q = TRUE THEN
                    State := 3;
                END_IF;
            3:
                IF StartPB = FALSE THEN
                    State := 0;
                END_IF;
        END_CASE;

        CASE State OF
            1:
                C1 := FALSE;
                C2 := TRUE;
                C3 := FALSE;
                TON_C1(IN := TRUE, PT := T#2s);
            2:
                C1 := TRUE;
                C2 := TRUE;
                C3 := TRUE;
                TON_C2(IN := TRUE, PT := T#2s);
            3:
                C1 := TRUE;
                C2 := TRUE;
                C3 := TRUE;
                TON_C3(IN := TRUE, PT := T#2s);
            ELSE:
                C1 := FALSE;
                C2 := FALSE;
                C3 := FALSE;
        END_CASE;

        IF StartPB = TRUE AND State = 0 THEN
            State := 1;
        END_IF;

        IF StopPB = TRUE OR State = 0 THEN
            State := 0;
        END_IF;

        IF TON_C1.Q = TRUE AND TON_C2.Q = TRUE AND TON_C3.Q = TRUE THEN
            State := 3;
        END_IF;

    ELSE
        State := 0;
    END_IF;
ELSE
    State := 0;
END_IF;

